import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay `keys[i] -> values[i]` on the defaults mode="fast", level="3".

    Returns the resulting values ordered as: mode, level, then every other
    key's value in the order the key first appears in `keys`.

    - A given "mode" or "level" replaces the default value.
    - If a key repeats, the last value wins; the key keeps the position of
      its first appearance.
    - Raises ValueError if `keys` and `values` differ in length.
    - Pure function: performs no I/O and does not mutate its arguments.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_defaults_when_empty() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_only() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level_only() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_any_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_in_given_order() -> None:
    assert settings(["z", "a", "m"], ["1", "2", "3"]) == ["fast", "3", "1", "2", "3"]


def test_extras_mixed_with_known_keys() -> None:
    keys = ["color", "level", "name", "mode"]
    values = ["red", "7", "bob", "slow"]
    assert settings(keys, values) == ["slow", "7", "red", "bob"]


def test_duplicate_known_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_duplicate_extra_key_last_wins_first_position() -> None:
    keys = ["x", "y", "x"]
    values = ["1", "2", "3"]
    assert settings(keys, values) == ["fast", "3", "3", "2"]


def test_empty_string_value_is_kept() -> None:
    assert settings(["mode", "k"], ["", ""]) == ["", "3", ""]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])


def test_inputs_not_mutated() -> None:
    keys = ["mode", "x"]
    values = ["slow", "1"]
    settings(keys, values)
    assert keys == ["mode", "x"]
    assert values == ["slow", "1"]

